416	                            background="bg-fill-brand"
417	                            borderRadius="full"
418	                            padding="100"
419	                            minWidth="24px"
420	                            minHeight="24px"
421	                          >
422	                            <Text
423	                              as="span"
424	                              variant="bodySm"
425	                              fontWeight="bold"
426	                              alignment="center"
427	                              tone="text-inverse"
428	                            >
429	                              {item.step}
430	                            </Text>
431	                          </Box>
432	                          <Text as="h3" variant="headingSm">
433	                            {item.title}
434	                          </Text>
